report_script:
# Eye Revenue on Hand: approved deals' Sales Orders by service type, less what is invoiced.
flt = frappe.utils.flt
rows = []
deals = frappe.get_all("Opportunity", filters={"sales_stage": "Quote approved", "custom_sales_order": ["is", "set"]},
                       fields=["name", "customer_name", "party_name", "currency", "custom_sales_order"])
for d in deals:
    if filters.get("customer") and d.party_name != filters.get("customer"):
        continue
    billed = {}
    requested = {}
    for b in frappe.get_all("Billing Request", filters={"opportunity": d.name}, fields=["name", "billing_stage"]):
        done = b.billing_stage in ("Invoiced", "Collected")
        for it in frappe.get_all("Billing Request Item", filters={"parent": b.name, "parenttype": "Billing Request"},
                                 fields=["so_detail", "amount"]):
            if done:
                billed[it.so_detail] = billed.get(it.so_detail, 0) + flt(it.amount)
            else:
                requested[it.so_detail] = requested.get(it.so_detail, 0) + flt(it.amount)
    by_type = {}
    for i in frappe.get_all("Sales Order Item", filters={"parent": d.custom_sales_order, "parenttype": "Sales Order"},
                            fields=["name", "custom_service_type", "amount"]):
        t = i.custom_service_type or _("Not set")
        if filters.get("service_type") and t != filters.get("service_type"):
            continue
        x = by_type.get(t) or {"order": 0, "requested": 0, "invoiced": 0}
        x["order"] = x["order"] + flt(i.amount)
        x["requested"] = x["requested"] + requested.get(i.name, 0)
        x["invoiced"] = x["invoiced"] + billed.get(i.name, 0)
        by_type[t] = x
    for t in sorted(by_type):
        x = by_type[t]
        rows.append({"opportunity": d.name, "customer_name": d.customer_name, "service_type": t, "currency": d.currency,
                     "order_value": x["order"], "requested": x["requested"], "invoiced": x["invoiced"],
                     "on_hand": x["order"] - x["invoiced"]})
columns = [
    {"fieldname": "opportunity", "label": _("Deal"), "fieldtype": "Link", "options": "Opportunity", "width": 160},
    {"fieldname": "customer_name", "label": _("Customer"), "fieldtype": "Data", "width": 200},
    {"fieldname": "service_type", "label": _("Service Type"), "fieldtype": "Data", "width": 140},
    {"fieldname": "currency", "label": _("Currency"), "fieldtype": "Link", "options": "Currency", "width": 80, "hidden": 1},
    {"fieldname": "order_value", "label": _("Order Value"), "fieldtype": "Currency", "options": "currency", "width": 130},
    {"fieldname": "requested", "label": _("Requested, Not Invoiced"), "fieldtype": "Currency", "options": "currency", "width": 160},
    {"fieldname": "invoiced", "label": _("Invoiced"), "fieldtype": "Currency", "options": "currency", "width": 130},
    {"fieldname": "on_hand", "label": _("Revenue on Hand"), "fieldtype": "Currency", "options": "currency", "width": 150},
]
data = columns, rows

# Eye Billing Pipeline: invoice requests by stage and expected month.
flt = frappe.utils.flt
cond = {}
if filters.get("from_date") and filters.get("to_date"):
    cond["expected_date"] = ["between", [filters.get("from_date"), filters.get("to_date")]]
groups = {}
for b in frappe.get_all("Billing Request", filters=cond, fields=["billing_stage", "expected_date", "total", "currency"]):
    key = (str(b.expected_date or "")[:7], b.billing_stage, b.currency)
    g = groups.get(key) or {"count": 0, "total": 0}
    g["count"] = g["count"] + 1
    g["total"] = g["total"] + flt(b.total)
    groups[key] = g
order = {"To be invoiced": 1, "Finance, please issue": 2, "Invoiced": 3, "Collected": 4}
rows = []
for sort_key, key in sorted([((k[0], order.get(k[1], 9), k[2]), k) for k in groups]):
    rows.append({"month": key[0], "stage": key[1], "currency": key[2], "requests": groups[key]["count"], "total": groups[key]["total"]})
columns = [
    {"fieldname": "month", "label": _("Expected Month"), "fieldtype": "Data", "width": 120},
    {"fieldname": "stage", "label": _("Stage"), "fieldtype": "Link", "options": "Billing Stage", "width": 170},
    {"fieldname": "currency", "label": _("Currency"), "fieldtype": "Link", "options": "Currency", "width": 80},
    {"fieldname": "requests", "label": _("Requests"), "fieldtype": "Int", "width": 90},
    {"fieldname": "total", "label": _("Total"), "fieldtype": "Currency", "options": "currency", "width": 140},
]
data = columns, rows
